<script setup lang="ts">
import {ref,computed,onMounted,onUnmounted,watch} from 'vue'
import {Boxes,Terminal,FolderOpen,Users,ShieldCheck,RefreshCw,Plus,LogOut,Copy,ChevronRight,Play,Trash2,Clock,FileText,ArrowUpToLine} from '@lucide/vue'
import {api,APIError,type Project,type Sandbox,type Audit,type Member} from './api'
import LoginForm from './LoginForm.vue'
import Workspaces from './Workspaces.vue'
import type {PersistentWorkspace,RunContext} from './api'
const token=ref(sessionStorage.getItem('olixops.token')||'')
const user=ref<{userId:string;name:string;admin:boolean}|null>(null),projects=ref<Project[]>([]),projectId=ref(''),sandboxes=ref<Sandbox[]>([]),audits=ref<Audit[]>([]),members=ref<Member[]>([])
const selectedRun=ref<RunContext|null>(null)
const tab=ref('sandboxes'),selected=ref<Sandbox|null>(null),panel=ref('command'),busy=ref(false),error=ref(''),notice=ref(''),modal=ref(''),projectName=ref(''),memberId=ref(''),memberRole=ref('member')
const settings=ref({images:[] as string[],maxTtl:86400,cpu:'1',memory:'1Gi',workspaceEnabled:false}),form=ref({name:'',image:'',ttl:3600,workspaceId:''}),requestKey=ref('')
const command=ref('pwd && ls -la'),background=ref(false),commandId=ref(''),logCursor=ref(0),output=ref(''),filePath=ref('/workspace/app.py'),content=ref(''),previewPort=ref(8000),previewPath=ref('/health'),fileList=ref<unknown[]>([])
const project=computed(()=>projects.value.find(p=>p.id===projectId.value)),canManage=computed(()=>!!user.value?.admin||['owner','maintainer'].includes(project.value?.role||'')),canEditMembers=computed(()=>!!user.value?.admin||project.value?.role==='owner')
const operable=computed(()=>!!selected.value?.backendId&&!['Deleted','Expired','Failed','Deleting'].includes(selected.value?.state||''))
const active=computed(()=>sandboxes.value.filter(b=>!['Deleted','Expired','Failed'].includes(b.state)).length)
const titles:Record<string,string>={sandboxes:'沙箱实例',workspaces:'持久化工作区',members:'项目成员',audit:'操作审计'}
function logout(){token.value='';user.value=null;selectedRun.value=null;sessionStorage.removeItem('olixops.token');projects.value=[];sandboxes.value=[];selected.value=null}
async function run(fn:()=>Promise<void>){if(busy.value)return;busy.value=true;error.value='';notice.value='';try{await fn()}catch(e){if(e instanceof APIError&&e.status===401)logout();error.value=e instanceof APIError&&e.status===413?'响应超过大小限制；日志每次最多读取 1 MiB，请提高日志游标或先在沙箱内筛选日志。':e instanceof Error?e.message:String(e)}finally{busy.value=false}}
async function login(username:string,password:string){await run(async()=>{
 let result:{accessToken:string}
 try{result=await api('pub/auth/login','',{username,password})}catch(e){if(e instanceof APIError&&e.status===401)throw new Error('账号或密码不正确');if(e instanceof APIError&&e.status===429)throw new Error('尝试过于频繁，请一分钟后再试');throw e}
 token.value=result.accessToken;await initialize();sessionStorage.setItem('olixops.token',token.value)
})}
async function signout(){await run(async()=>{await api('auth/logout',token.value,{});logout()})}
async function initialize(){user.value=await api('user/profile',token.value);settings.value=await api('settings',token.value);projects.value=await api('projects',token.value);form.value.image=settings.value.images[0]||'';projectId.value=projects.value[0]?.id||'';await load()}
async function load(){if(!projectId.value){sandboxes.value=[];return};const id=projectId.value;const list=await api<Sandbox[]>('sandbox/list',token.value,{projectId:id});if(id!==projectId.value)return;sandboxes.value=list;if(selected.value){selected.value=list.find(b=>b.id===selected.value?.id)||null}if(tab.value==='audit')audits.value=await api('audit/list',token.value,{projectId:id});if(tab.value==='members'&&canManage.value)members.value=await api('project/members',token.value,{projectId:id})}
async function changeProject(){selected.value=null;selectedRun.value=null;audits.value=[];members.value=[];output.value='';await run(load)}
async function changeTab(t:string){tab.value=t;await run(load)}
function openCreate(){requestKey.value=crypto.randomUUID();form.value.name='';form.value.workspaceId='';modal.value='sandbox'}
function startWorkspace(w:PersistentWorkspace){openCreate();form.value.workspaceId=w.id;form.value.name=w.name+'-runtime'}
async function openRuntime(id:string,context?:RunContext){await run(async()=>{tab.value='sandboxes';await load();const target=sandboxes.value.find(s=>s.id===id);if(!target)throw new Error('运行实例不存在或当前无权访问，请返回对话刷新状态。');selected.value=target;selectedRun.value=context||null;output.value='';content.value='';fileList.value=[];commandId.value=''})}
async function create(){await run(async()=>{if(modal.value==='project'){const p=await api<{id:string}>('project/create',token.value,{name:projectName.value});projects.value=await api('projects',token.value);projectId.value=p.id;selected.value=null;selectedRun.value=null}else{const r=await api<{sandbox:Sandbox;message?:string}>('sandbox/create',token.value,{...form.value,projectId:projectId.value,requestKey:requestKey.value});tab.value='sandboxes';selectedRun.value=null;selected.value=r.sandbox;notice.value=r.message||'沙箱创建请求已处理'};modal.value='';await load()})}
async function action(action:string,extra:Record<string,unknown>={}){if(!selected.value)return;const id=selected.value.id;return api<unknown>('sandbox/action',token.value,{id,action,...(selectedRun.value&&!['sync','delete','renew'].includes(action)?{runContextId:selectedRun.value.id}:{}),...extra})}
async function lifecycle(a:string){if(a==='delete'&&!confirm('确认销毁这个沙箱？临时可写层文件将丢失，已挂载的持久工作区仍保留。'))return;await run(async()=>{await action(a,a==='renew'?{ttl:3600}:{});await load();notice.value=a==='delete'?'销毁请求已处理':'状态已更新'})}
async function execute(){await run(async()=>{const r=await action('command',{command:command.value,background:background.value});output.value=JSON.stringify(r,null,2)})}
watch(commandId,()=>{logCursor.value=0})
async function logs(){await run(async()=>{const r=await action('logs',{commandId:commandId.value,cursor:logCursor.value}) as {output:string;cursor:number};output.value=r.output||'暂无新增日志';logCursor.value=r.cursor})}
function toBase64(s:string){const bytes=new TextEncoder().encode(s);let raw='';for(const b of bytes)raw+=String.fromCharCode(b);return btoa(raw)}
function fromBase64(s:string){return new TextDecoder().decode(Uint8Array.from(atob(s),c=>c.charCodeAt(0)))}
async function file(a:string){if(a==='remove'&&!confirm('确认删除 '+filePath.value+'？'))return;await run(async()=>{const r=await action(a,{path:filePath.value,...(a==='write'?{content:toBase64(content.value)}:{})});if(a==='read')content.value=fromBase64((r as {content:string}).content);else if(a==='files')fileList.value=r as unknown[];notice.value='文件操作完成'})}
async function upload(e:Event){const f=(e.target as HTMLInputElement).files?.[0];if(!f)return;if(f.size>4*1024*1024){error.value='文件不能超过 4 MiB';return};await run(async()=>{const bytes=new Uint8Array(await f.arrayBuffer());let raw='';for(const b of bytes)raw+=String.fromCharCode(b);await action('write',{path:filePath.value,content:btoa(raw)});notice.value='上传完成'})}
async function download(){await run(async()=>{const r=await action('read',{path:filePath.value}) as {content:string};const bytes=Uint8Array.from(atob(r.content),c=>c.charCodeAt(0));const href=URL.createObjectURL(new Blob([bytes]));const a=document.createElement('a');a.href=href;a.download=filePath.value.split('/').pop()||'download';a.click();URL.revokeObjectURL(href)})}
async function preview(){await run(async()=>{output.value=JSON.stringify(await action('preview',{port:previewPort.value,path:previewPath.value}),null,2)})}
async function setMember(){await run(async()=>{await api('project/member/set',token.value,{projectId:projectId.value,userId:memberId.value,role:memberRole.value});memberId.value='';await load();notice.value='成员权限已保存'})}
async function copy(s:string){try{await navigator.clipboard.writeText(s);notice.value='已复制'}catch{error.value='复制失败，请手动选择文本复制'}}
function pick(b:Sandbox){if(busy.value)return;selected.value=b;if(selectedRun.value?.sandboxId!==b.id)selectedRun.value=null;output.value='';content.value='';fileList.value=[];commandId.value=''}
function time(s?:string){return s?new Date(s).toLocaleString('zh-CN',{hour12:false}):'—'}
let timer:ReturnType<typeof setInterval>|undefined
onMounted(()=>{if(token.value)void run(initialize);timer=setInterval(()=>{if(user.value&&!busy.value&&tab.value==='sandboxes')void run(load)},15000)})
onUnmounted(()=>{if(timer)clearInterval(timer)})
</script>
<template>
<LoginForm v-if="!user" :busy="busy" :error="error" @submit="login"/>
<div v-else class="shell">
<aside><div class="brand"><Boxes :size="24"/><strong>OLIXOPS</strong></div><div class="product">AGENT PLATFORM <span>01</span></div><div class="nav-label">工作空间</div><button v-for="(label,key) in titles" :key="key" class="nav" :class="{active:tab===key}" :aria-label="label" :disabled="busy" @click="changeTab(key)"><component :is="key==='sandboxes'?Boxes:key==='workspaces'?FolderOpen:key==='members'?Users:ShieldCheck" :size="18"/>{{label}}</button><div class="aside-bottom"><span class="online"></span>平台控制台 <small>v0.1.0</small></div></aside>
<div class="workspace"><header><div class="breadcrumb">工作空间 <ChevronRight :size="14"/> {{project?.name||'选择项目'}}</div><div class="user"><span class="avatar">{{(user.name||user.userId).slice(0,1).toUpperCase()}}</span>{{user.name||user.userId}}<button class="icon" aria-label="退出登录" @click="signout" :disabled="busy"><LogOut :size="16"/></button></div></header>
<main><select class="mobile-nav" aria-label="页面导航" :value="tab" :disabled="busy" @change="changeTab(($event.target as HTMLSelectElement).value)"><option v-for="(label,key) in titles" :key="key" :value="key">{{label}}</option></select><div class="page-heading"><div><div class="eyebrow">WORKSPACE / {{tab.toUpperCase()}}</div><h1>{{titles[tab]}}</h1><p>{{tab==='sandboxes'?'为 AI 编程提供可管理、可追踪的执行环境。':tab==='members'?'通过项目角色管理协作范围。':tab==='workspaces'?'用户数据长期保存，对话关联原工作区继续使用。':'查询项目内的资源操作记录。'}}</p></div><button v-if="tab==='sandboxes'" class="primary" :disabled="busy||!projectId" @click="openCreate"><Plus :size="16"/>创建沙箱</button></div>
<div v-if="error" role="alert" class="error">{{error}}<button @click="error=''" aria-label="关闭错误">×</button></div><div v-if="notice" role="status" class="notice">{{notice}}</div>
<div class="toolbar"><div class="context"><label for="project">项目</label><select id="project" v-model="projectId" :disabled="busy" @change="changeProject"><option value="" disabled>选择项目</option><option v-for="p in projects" :key="p.id" :value="p.id">{{p.name}}</option></select><span v-if="project" class="tag">{{project.role}}</span></div><div class="actions"><button :disabled="busy" @click="modal='project';projectName='' "><Plus :size="15"/>新建项目</button><button class="icon" :disabled="busy" aria-label="刷新" @click="run(load)"><RefreshCw :size="16" :class="{spin:busy}"/></button></div></div>
<div v-if="!projectId" class="empty"><FolderOpen :size="32"/><h2>创建第一个项目</h2><p>项目用于组织成员、沙箱配额和操作记录。</p><button @click="modal='project'">新建项目</button></div>
<template v-else-if="tab==='sandboxes'">
<div class="summary"><span><i class="online"></i>可见活跃沙箱 <strong>{{active}}</strong></span><span>项目配额 <strong>{{project?.quota}}</strong></span><span>默认规格 <strong>{{settings.cpu}} CPU / {{settings.memory}}</strong></span><small>每 15 秒刷新 · 普通成员仅查看自己的沙箱</small></div>
<div class="table-wrap"><table><thead><tr><th>沙箱名称 / 标识</th><th>状态</th><th>镜像</th><th>所有者</th><th>过期时间</th><th></th></tr></thead><tbody><tr v-for="s in sandboxes" :key="s.id" :class="{selected:selected?.id===s.id}" @click="pick(s)"><td><button class="text name" @click.stop="pick(s)">{{s.name}}</button><small class="mono">{{s.id.slice(0,12)}}</small></td><td><span class="status" :class="s.state.toLowerCase()">{{s.state}}</span></td><td class="mono">{{s.image}}</td><td>{{s.ownerId}}</td><td>{{time(s.expiresAt)}}</td><td><ChevronRight :size="16"/></td></tr><tr v-if="!sandboxes.length"><td colspan="6" class="empty-cell">暂无沙箱，点击右上方创建。</td></tr></tbody></table></div>
<section v-if="selected" class="detail"><div class="toolbar"><div class="context"><strong>{{selected.name}}</strong><span class="status" :class="selected.state.toLowerCase()">{{selected.state}}</span><button class="icon" aria-label="复制沙箱 ID" @click="copy(selected.id)"><Copy :size="14"/></button></div><div class="actions"><button :disabled="busy" @click="lifecycle('sync')"><RefreshCw :size="14"/>同步</button><button :disabled="busy||!operable" @click="lifecycle('renew')"><Clock :size="14"/>续期 1 小时</button><button class="danger" :disabled="busy||['Deleted','Expired','Failed'].includes(selected.state)" @click="lifecycle('delete')"><Trash2 :size="14"/>销毁</button></div></div>
<p v-if="selectedRun" class="detail-hint">当前执行 {{selectedRun.id.slice(0,12)}} · 已固定对话绑定版本 {{selectedRun.bindingVersion}}。后台服务可能持续写文件。</p><p v-if="!operable" class="detail-hint">当前状态不允许执行或修改文件；可同步状态或查看操作审计。</p><div class="tabs"><button v-for="(label,key) in {command:'命令与日志',files:'文件管理',preview:'接口验证'}" :key="key" :class="{chosen:panel===key}" @click="panel=key;output='' "><component :is="key==='command'?Terminal:key==='files'?FileText:Play" :size="15"/>{{label}}</button></div>
<div class="detail-content" v-if="panel==='command'"><label>执行命令<textarea v-model="command" class="code" rows="3" spellcheck="false"/></label><div class="command-bar"><label class="checkbox"><input v-model="background" type="checkbox"/>后台执行</label><button class="primary" :disabled="busy||!operable" @click="execute"><Play :size="14"/>执行</button></div><div class="inline"><input v-model="commandId" placeholder="后台执行返回的 command ID" aria-label="命令 ID"/><label>日志游标<input v-model.number="logCursor" type="number" min="0" step="1" aria-label="日志游标"/></label><button :disabled="busy||!operable||!commandId" @click="logs">读取新增日志</button></div><pre class="output" tabindex="0">{{output||'命令输出将在这里显示。前台命令最长执行 60 秒。'}}</pre></div>
<div class="detail-content" v-if="panel==='files'"><label>沙箱内绝对路径<input v-model="filePath" placeholder="/workspace/app.py"/></label><div class="file-actions"><button :disabled="busy||!operable" @click="file('files')">列出目录</button><button :disabled="busy||!operable" @click="file('read')">读取</button><button :disabled="busy||!operable" @click="file('write')">保存文本</button><button :disabled="busy||!operable" @click="download">下载</button><label class="upload"><ArrowUpToLine :size="14"/>上传<input type="file" :disabled="busy||!operable" @change="upload"/></label><button class="danger" :disabled="busy||!operable" @click="file('remove')">删除文件</button></div><textarea v-model="content" class="code" rows="10" placeholder="文本文件内容，最大 4 MiB" spellcheck="false"/><pre v-if="fileList.length" class="output">{{JSON.stringify(fileList,null,2)}}</pre></div>
<div class="detail-content" v-if="panel==='preview'"><p>请求经平台授权后转发，仅展示响应内容。支持 HTTP GET 接口验证。</p><div class="inline"><label>端口<input v-model.number="previewPort" type="number" min="1024" max="65535"/></label><label class="grow">接口路径<input v-model="previewPath" placeholder="/health"/></label><button class="primary" :disabled="busy||!operable" @click="preview">发送请求</button></div><pre class="output">{{output||'先在沙箱内启动监听 0.0.0.0 的应用。'}}</pre></div>
</section></template>
<Workspaces v-else-if="tab==='workspaces'" :key="projectId" :token="token" :project-id="projectId" :enabled="settings.workspaceEnabled" :images="settings.images" :max-ttl="settings.maxTtl" @expired="logout" @start="startWorkspace" @open="openRuntime"/>
<template v-else-if="tab==='members'"><div v-if="!canManage" class="empty">仅项目负责人和维护者可查看成员。</div><template v-else><div class="member-form" v-if="canEditMembers"><input v-model="memberId" placeholder="员工 staffuserid" aria-label="员工 ID"/><select v-model="memberRole" aria-label="角色"><option value="member">member · 仅操作自己的沙箱</option><option value="maintainer">maintainer · 管理项目内沙箱</option></select><button class="primary" :disabled="busy||!memberId" @click="setMember">添加 / 更新成员</button></div><div class="table-wrap"><table><thead><tr><th>员工 ID</th><th>项目角色</th><th>权限范围</th></tr></thead><tbody><tr v-for="m in members" :key="m.userId"><td>{{m.userId}}</td><td><span class="tag">{{m.role}}</span></td><td>{{m.role==='member'?'仅自己的沙箱':m.role==='owner'?'管理成员及全部项目沙箱':'全部项目沙箱'}}</td></tr></tbody></table></div></template></template>
<div v-else class="table-wrap"><table><thead><tr><th>时间</th><th>操作人</th><th>动作</th><th>资源 ID</th><th>结果</th></tr></thead><tbody><tr v-for="a in audits" :key="a.id"><td>{{time(a.createAt)}}</td><td>{{a.actor}}</td><td class="mono">{{a.action}}</td><td class="mono">{{a.workspaceId||a.sandboxId||'—'}}</td><td>{{a.outcome}}</td></tr><tr v-if="!audits.length"><td colspan="5" class="empty-cell">暂无操作记录</td></tr></tbody></table></div>
</main><footer>OLIXOPS / AI DEVELOPMENT INFRASTRUCTURE <span>受控执行 · 项目协作 · 操作追踪</span></footer></div>
<div v-if="modal" class="modal-backdrop" @click.self="!busy&&(modal='')"><form class="modal" @submit.prevent="create"><h2>{{modal==='project'?'新建项目':'创建沙箱'}}</h2><template v-if="modal==='project'"><label>项目名称<input v-model="projectName" maxlength="80" required autofocus/></label><p>你将成为项目负责人，配额由后端配置分配。</p></template><template v-else><label>沙箱名称<input v-model="form.name" required maxlength="80"/></label><label>镜像<select v-model="form.image"><option v-for="i in settings.images" :key="i" :value="i">{{i}}</option></select></label><label>存活时间（秒）<input v-model.number="form.ttl" type="number" min="60" :max="settings.maxTtl" required/></label><p>规格：{{settings.cpu}} CPU / {{settings.memory}}。{{form.workspaceId?'已选择持久化工作区，/workspace 文件保留。':'当前为临时沙箱；需要保留文件请从持久化工作区启动。'}}</p></template><div v-if="error" role="alert" class="error">{{error}}</div><div class="actions"><button type="button" :disabled="busy" @click="modal=''">取消</button><button class="primary" :disabled="busy">{{busy?'处理中…':'确认创建'}}</button></div></form></div>
</div>
</template>
